INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d1d2d3d4-4405-4000-8000-000000000005', 'b1b2c3d4-4444-4000-8000-000000000004', 5, 'A Ressurreição do Corpo', 'Esperança escatológica', '{"text": "A Teologia do Corpo n\u00e3o termina na morte \u2014 aponta para a ressurrei\u00e7\u00e3o.\n\nQuando os saduceus perguntaram a Jesus sobre o casamento na ressurrei\u00e7\u00e3o, Ele respondeu: \"Na ressurrei\u00e7\u00e3o, nem se casam nem se d\u00e3o em casamento, mas s\u00e3o como anjos no c\u00e9u\" (Mt 22,30).\n\nS\u00e3o Jo\u00e3o Paulo II interpreta: na ressurrei\u00e7\u00e3o, o significado esponsal do corpo ser\u00e1 plenamente realizado \u2014 n\u00e3o no matrim\u00f4nio terreno, mas na **comunh\u00e3o perfeita com Deus**.\n\n**O que isso significa para n\u00f3s agora?**\n- O celibato/virgindade consagrada \u00e9 um sinal antecipado da vida futura\n- O matrim\u00f4nio \u00e9 sacramento que aponta para a uni\u00e3o Cristo-Igreja\n- Toda voca\u00e7\u00e3o \u00e9 chamado ao amor que transcende a morte\n\n\"O corpo glorioso ser\u00e1 a revela\u00e7\u00e3o definitiva da beleza de Deus.\"", "scripture": "1Cor 15,44 \u2014 Semeia-se corpo animal, ressuscita corpo espiritual."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;